import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const excludedDirectories = [
  '.git', 'node_modules', 'dist', 'target', 'coverage', '.nx', '.idea',
  '.codex-tmp', '.worktrees', '.artifacts', '.updater', '.webview2-test',
  '.cxx', '.gradle', '.expo', '.prerender',
  '__pycache__', '.pytest_cache', '.mypy_cache', '.ruff_cache', '.venv',
  'playwright-report', 'test-results', 'blob-report',
  'docs', 'public', 'resources', 'icons', 'gen',
];

// Native platform trees are generated by Expo. Keep source directories such as apps/web/build.
const excludedPaths = [
  'apps/native/(?:android|ios)',
  'apps/native/plugins/connectivity/build',
  'apps/admin/testdata/(?:bin|results)',
  '\\.codex-tmp-.+',
];
const excludedFileNames = [
  'package-lock\\.json', 'npm-shrinkwrap\\.json', 'pnpm-lock\\.yaml', 'go\\.sum',
];
const excludedExtensions = [
  'md', 'mdx', 'rst', 'lock', 'log', 'map', 'tsbuildinfo', 'svg',
  'zip', 'tar', 'tgz', 'gz', 'bz2', 'xz', '7z', 'rar', 'apk', 'aab', 'ipa', 'jar',
];
const separator = '[/\\\\]';
const excludedPathPattern = excludedPaths.map((directory) => directory.replaceAll('/', separator)).join('|');
const args = [
  '.',
  `--exclude-dir=${excludedDirectories.join(',')}`,
  '--fullpath',
  `--not-match-d=(?:^|${separator})(?:${excludedPathPattern})(?:${separator}|$)`,
  `--not-match-f=(?:^|${separator})(?:${excludedFileNames.join('|')})$|\\.min\\.(?:js|css)$`,
  `--exclude-ext=${excludedExtensions.join(',')}`,
  // Exclude plain text documents without dropping build scripts named CMakeLists.txt.
  '--exclude-lang=Text',
  ...process.argv.slice(2),
];

const result = spawnSync('cloc', args, {
  cwd: fileURLToPath(new URL('..', import.meta.url)),
  stdio: 'inherit',
  windowsHide: true,
});
if (result.error) console.error(result.error.message);
process.exitCode = result.status ?? 1;
